namespace SrpLab;
public sealed class AllergenScanner { public IReadOnlyList<string> Scan(IEnumerable<List<string>> ingredientLists) { var hits=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var ingredients in ingredientLists)foreach(var ing in ingredients){if(ing.Contains("milk")||ing.Contains("cheese")||ing.Contains("butter"))hits.Add("dairy");if(ing.Contains("wheat")||ing.Contains("flour")||ing.Contains("bread"))hits.Add("gluten");if(ing.Contains("peanut")||ing.Contains("almond")||ing.Contains("cashew"))hits.Add("nuts");if(ing.Contains("shrimp")||ing.Contains("prawn")||ing.Contains("crab"))hits.Add("shellfish");}return hits.OrderBy(x=>x).ToList();} }
public sealed class KitchenReadyTimeEstimator { public int Estimate(IEnumerable<int> prepTimes,int stations,bool hasAllergens){if(stations<=0)stations=1;var times=prepTimes.ToList();var parallel=(int)Math.Ceiling(times.Sum()/(double)stations);if(hasAllergens)parallel+=3;return Math.Max(parallel,times.Count==0?0:times.Max());} }
public sealed class ThermalTicketRenderer { public string Render(int number,IEnumerable<(string Item,int Prep)> items,int eta,IReadOnlyList<string> allergens){var line=new string('=',32);var body=string.Join('\n',items.Select(i=>$"* {i.Item.ToUpperInvariant()} ({i.Prep}m)"));var allergy=allergens.Count==0?"ALLERGENS: none":"ALLERGENS: "+string.Join(",",allergens);return $"{line}\nORDER #{number}\nETA {eta} MIN\n{body}\n{allergy}\n{line}\n";} }
public sealed class ExpoLaneSelector { public string Select(IReadOnlyList<string> allergens,int eta){return allergens.Count>0?"LANE-ALLERGY":eta>20?"LANE-SLOW":"LANE-FAST";} }
